// Unsigned magnitude comparator
module comparator #(
    parameter WIDTH = 8
)(
    input  [WIDTH-1:0] a, b,
    output             eq, gt, lt
);
    assign eq = (a == b);
    assign gt = (a >  b);
    assign lt = (a <  b);
endmodule

module decoder_3to8 (
    input  [2:0] a,
    input        en,
    output [7:0] y
);
    assign y = en ? (8'b0000_0001 << a) : 8'b0000_0000;
endmodule

module demux_1to4 (
    input            din,
    input      [1:0] sel,
    output reg [3:0] y
);
    always @* begin
        y      = 4'b0000;
        y[sel] = din;
    end
endmodule

module full_adder (
    input  a, b, cin,
    output sum, cout
);
    assign sum  = a ^ b ^ cin;
    assign cout = (a & b) | (cin & (a ^ b));
endmodule

module half_adder (
    input  a, b,
    output sum, carry
);
    assign sum   = a ^ b;
    assign carry = a & b;
endmodule

module mux_2to1 #(
    parameter WIDTH = 1
)(
    input  [WIDTH-1:0] a, b,
    input              sel,
    output [WIDTH-1:0] y
);
    assign y = sel ? b : a;
endmodule

module mux_4to1 #(
    parameter WIDTH = 1
)(
    input      [WIDTH-1:0] a, b, c, d,
    input      [1:0]       sel,
    output reg [WIDTH-1:0] y
);
    always @* begin
        case (sel)
            2'd0:    y = a;
            2'd1:    y = b;
            2'd2:    y = c;
            default: y = d;
        endcase
    end
endmodule

// Highest set bit wins. WIDTH must be >= 2.
module priority_encoder #(
    parameter WIDTH = 8
)(
    input      [WIDTH-1:0]         in,
    output reg [$clog2(WIDTH)-1:0] index,
    output reg                     valid
);
    integer i;
    always @* begin
        index = 0;
        valid = 1'b0;
        for (i = 0; i < WIDTH; i = i + 1)
            if (in[i]) begin        // later (higher) i overrides earlier ones
                index = i[$clog2(WIDTH)-1:0];
                valid = 1'b1;
            end
    end
endmodule

// Logical barrel shifter. WIDTH must be a power of two (>= 2).
// dir = 0: shift left, dir = 1: shift right
module barrel_shifter #(
    parameter WIDTH = 8
)(
    input  [WIDTH-1:0]         data,
    input  [$clog2(WIDTH)-1:0] shamt,
    input                      dir,
    output [WIDTH-1:0]         y
);
    assign y = dir ? (data >> shamt) : (data << shamt);
endmodule

// Carry-lookahead adder: every carry is a flat function of p, g and cin
// (no carry ripples through the previous stage).
//   c[i+1] = g[i] | p[i]g[i-1] | ... | p[i]..p[1]g[0] | p[i]..p[0]cin
module carry_lookahead_adder #(
    parameter WIDTH = 4
)(
    input  [WIDTH-1:0] a, b,
    input              cin,
    output [WIDTH-1:0] sum,
    output             cout
);
    wire [WIDTH-1:0] p = a ^ b;
    wire [WIDTH-1:0] g = a & b;
    reg  [WIDTH:0]   c;
    integer i, j, k;
    reg term;
    always @* begin
        c[0] = cin;
        for (i = 0; i < WIDTH; i = i + 1) begin
            c[i+1] = g[i];
            for (j = 0; j < i; j = j + 1) begin      // g[j] propagated through p[j+1..i]
                term = g[j];
                for (k = j + 1; k <= i; k = k + 1) term = term & p[k];
                c[i+1] = c[i+1] | term;
            end
            term = cin;                               // cin propagated through p[0..i]
            for (k = 0; k <= i; k = k + 1) term = term & p[k];
            c[i+1] = c[i+1] | term;
        end
    end
    assign sum  = p ^ c[WIDTH-1:0];
    assign cout = c[WIDTH];
endmodule

// Counts leading zeros from the MSB. count = WIDTH when in == 0.
module leading_zero_detector #(
    parameter WIDTH = 8
)(
    input      [WIDTH-1:0]           in,
    output reg [$clog2(WIDTH+1)-1:0] count,
    output                           zero
);
    integer i;
    reg     found;
    always @* begin
        count = 0;
        found = 1'b0;
        for (i = WIDTH-1; i >= 0; i = i - 1) begin
            if (in[i]) found = 1'b1;
            else if (!found) count = count + 1'b1;
        end
    end
    assign zero = ~|in;
endmodule

// Signed multiply-accumulate. ACC_W defaults to 2*WIDTH+1; add guard bits
// (larger ACC_W) if you accumulate many worst-case products.
module mac_unit #(
    parameter int WIDTH = 16,
    parameter int ACC_W = 2*WIDTH + 1
)(
    input  logic                    clk, rst,
    input  logic                    clr,      // synchronous accumulator clear
    input  logic                    en,
    input  logic signed [WIDTH-1:0] a, b,
    output logic signed [ACC_W-1:0] y
);
    logic signed [2*WIDTH-1:0] prod;
    assign prod = a * b;
    always_ff @(posedge clk) begin
        if (rst || clr) y <= '0;
        else if (en)    y <= y + ACC_W'(prod);
    end
endmodule

// Structural ripple-carry adder built from full adders
module ripple_carry_adder #(
    parameter WIDTH = 8
)(
    input  [WIDTH-1:0] a, b,
    input              cin,
    output [WIDTH-1:0] sum,
    output             cout
);
    wire [WIDTH:0] c;
    assign c[0] = cin;
    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : g_fa
            full_adder fa (.a(a[i]), .b(b[i]), .cin(c[i]),
                           .sum(sum[i]), .cout(c[i+1]));
        end
    endgenerate
    assign cout = c[WIDTH];
endmodule

// Unsigned saturating adder: clamps to all-ones on overflow
module saturating_adder #(
    parameter WIDTH = 8
)(
    input      [WIDTH-1:0] a, b,
    output reg [WIDTH-1:0] y
);
    reg [WIDTH:0] tmp;
    always @* begin
        tmp = {1'b0, a} + {1'b0, b};
        y   = tmp[WIDTH] ? {WIDTH{1'b1}} : tmp[WIDTH-1:0];
    end
endmodule

// Divides clk by DIV (output period = DIV input cycles), glitch-free
// (registered output). High time = floor(DIV/2) cycles, so odd DIV gives
// a duty cycle slightly below 50%. DIV < 2 passes the clock through.
// NOTE: on FPGAs prefer a clock-enable or a PLL/MMCM over a fabric-divided clock.
module clock_divider #(
    parameter int DIV = 2
)(
    input  logic clk, rst,
    output logic clk_out
);
    generate
        if (DIV < 2) begin : g_bypass
            assign clk_out = clk;
        end else begin : g_div
            localparam int W    = $clog2(DIV);
            localparam int HIGH = DIV / 2;
            logic [W-1:0] count;
            always_ff @(posedge clk) begin
                if (rst) begin
                    count   <= '0;
                    clk_out <= 1'b0;
                end else if (count == W'(DIV - 1)) begin
                    count   <= '0;
                    clk_out <= 1'b1;
                end else begin
                    count <= count + 1'b1;
                    if (count == W'(HIGH - 1)) clk_out <= 1'b0;
                end
            end
        end
    endgenerate
endmodule

module dff (
    input  logic clk, rst,
    input  logic d,
    output logic q
);
    always_ff @(posedge clk) begin
        if (rst) q <= 1'b0;
        else     q <= d;
    end
endmodule

// Registered edge detector. rising/falling are 1-cycle pulses that appear
// one clock after the edge is sampled. signal_in must be synchronous to clk
// (pass asynchronous inputs through two_flop_synchronizer first).
module edge_detector (
    input  logic clk, rst,
    input  logic signal_in,
    output logic rising, falling
);
    logic prev;
    always_ff @(posedge clk) begin
        if (rst) begin
            prev    <= 1'b0;
            rising  <= 1'b0;
            falling <= 1'b0;
        end else begin
            rising  <=  signal_in & ~prev;
            falling <= ~signal_in &  prev;
            prev    <=  signal_in;
        end
    end
endmodule

// Twisted-ring counter: 2*WIDTH states. WIDTH must be >= 2.
module johnson_counter #(
    parameter int WIDTH = 4
)(
    input  logic             clk, rst, en,
    output logic [WIDTH-1:0] q
);
    initial if (WIDTH < 2) $error("johnson_counter: WIDTH must be >= 2");
    always_ff @(posedge clk) begin
        if (rst)     q <= '0;
        else if (en) q <= {q[WIDTH-2:0], ~q[WIDTH-1]};
    end
endmodule

module register #(
    parameter int WIDTH = 8
)(
    input  logic             clk, rst, en,
    input  logic [WIDTH-1:0] d,
    output logic [WIDTH-1:0] q
);
    always_ff @(posedge clk) begin
        if (rst)     q <= '0;
        else if (en) q <= d;
    end
endmodule

// One-hot ring counter: WIDTH states. WIDTH must be >= 2.
module ring_counter #(
    parameter int WIDTH = 4
)(
    input  logic             clk, rst, en,
    output logic [WIDTH-1:0] q
);
    initial if (WIDTH < 2) $error("ring_counter: WIDTH must be >= 2");
    always_ff @(posedge clk) begin
        if (rst)     q <= {{(WIDTH-1){1'b0}}, 1'b1};
        else if (en) q <= {q[WIDTH-2:0], q[WIDTH-1]};
    end
endmodule

// Serial-in / parallel-out shift register with parallel load (left shift).
// load has priority over shift. WIDTH must be >= 2.
module shift_register #(
    parameter int WIDTH = 8
)(
    input  logic             clk, rst, en,
    input  logic             load,
    input  logic             serial_in,
    input  logic [WIDTH-1:0] parallel_in,
    output logic [WIDTH-1:0] q,
    output logic             serial_out
);
    initial if (WIDTH < 2) $error("shift_register: WIDTH must be >= 2");
    always_ff @(posedge clk) begin
        if (rst)        q <= '0;
        else if (load)  q <= parallel_in;
        else if (en)    q <= {q[WIDTH-2:0], serial_in};
    end
    assign serial_out = q[WIDTH-1];
endmodule

// Debouncer with built-in 2-flop synchronizer for the asynchronous button.
// The output changes only after the input has been stable for COUNT_MAX cycles
// (default 500000 = 5 ms at 100 MHz).
module switch_debouncer #(
    parameter int COUNT_MAX = 500000
)(
    input  logic clk, rst,
    input  logic button,
    output logic debounced
);
    localparam int W = (COUNT_MAX < 2) ? 1 : $clog2(COUNT_MAX);
    logic [1:0]   sync;
    logic         btn;
    logic [W-1:0] count;
    assign btn = sync[1];
    always_ff @(posedge clk) begin
        if (rst) begin
            sync      <= 2'b00;
            count     <= '0;
            debounced <= 1'b0;
        end else begin
            sync <= {sync[0], button};
            if (btn == debounced)
                count <= '0;                       // input agrees with output: restart
            else if (count == W'(COUNT_MAX - 1)) begin
                debounced <= btn;                  // stable long enough: accept
                count     <= '0;
            end else
                count <= count + 1'b1;
        end
    end
endmodule

module t_flip_flop (
    input  logic clk, rst,
    input  logic t,
    output logic q
);
    always_ff @(posedge clk) begin
        if (rst)    q <= 1'b0;
        else if (t) q <= ~q;
    end
endmodule

module up_down_counter #(
    parameter int WIDTH = 8
)(
    input  logic             clk, rst, en,
    input  logic             up,          // 1 = count up, 0 = count down
    output logic [WIDTH-1:0] q
);
    always_ff @(posedge clk) begin
        if (rst)     q <= '0;
        else if (en) q <= up ? q + 1'b1 : q - 1'b1;   // wraps naturally
    end
endmodule

// Mealy detector for the bit sequence 1010 (serial, MSB first).
// detected is combinational: high in the same cycle the last bit arrives.
// OVERLAP = 0 : bits of a match cannot start the next match (default)
// OVERLAP = 1 : 1010101 contains two matches
module mealy_sequence_detector #(
    parameter bit OVERLAP = 1'b0
)(
    input  logic clk, rst,
    input  logic in_bit,
    output logic detected
);
    typedef enum logic [1:0] {S0, S1, S2, S3} state_t;   // bits matched so far: 0,1,10,101
    state_t state, next;
    always_ff @(posedge clk) begin
        if (rst) state <= S0;
        else     state <= next;
    end
    always_comb begin
        next     = state;
        detected = 1'b0;
        case (state)
            S0: if (in_bit) next = S1;
            S1: if (!in_bit) next = S2;
            S2: begin
                if (in_bit) next = S3;
                else        next = S0;
            end
            S3: begin
                if (in_bit) next = S1;
                else begin
                    detected = 1'b1;
                    next     = OVERLAP ? S2 : S0;
                end
            end
            default: next = S0;
        endcase
    end
endmodule

// Moore detector for the bit sequence 1010 (serial, MSB first).
// detected is registered-state based: high one cycle AFTER the last bit.
// OVERLAP = 0 (default) / 1 as in mealy_sequence_detector.
module moore_sequence_detector #(
    parameter bit OVERLAP = 1'b0
)(
    input  logic clk, rst,
    input  logic in_bit,
    output logic detected
);
    typedef enum logic [2:0] {S0, S1, S2, S3, S4} state_t;   // S4 = 1010 matched
    state_t state, next;
    always_ff @(posedge clk) begin
        if (rst) state <= S0;
        else     state <= next;
    end
    always_comb begin
        next = state;
        case (state)
            S0: if (in_bit) next = S1;
            S1: if (!in_bit) next = S2;
            S2: begin
                if (in_bit) next = S3;
                else        next = S0;
            end
            S3: begin
                if (in_bit) next = S1;
                else        next = S4;
            end
            S4: begin
                if (in_bit) next = OVERLAP ? S3 : S1;
                else        next = S0;
            end
            default: next = S0;
        endcase
    end
    assign detected = (state == S4);
endmodule

// Two-road traffic light controller (timed).
// Light encoding {green, yellow, red}: 3'b100 green, 3'b010 yellow, 3'b001 red.
// Sequence: NS green -> NS yellow -> EW green -> EW yellow -> ...
// NS and EW are never green/yellow at the same time. The yellow phase acts
// as the clearance interval; add an all-red state if your intersection needs one.
module traffic_light_controller #(
    parameter int GREEN_CYCLES  = 8,
    parameter int YELLOW_CYCLES = 2
)(
    input  logic       clk, rst,
    output logic [2:0] ns, ew
);
    typedef enum logic [1:0] {NS_G, NS_Y, EW_G, EW_Y} state_t;
    state_t state, next;
    logic [15:0] timer;
    logic [15:0] limit;
    always_comb begin
        case (state)
            NS_G:    next = NS_Y;
            NS_Y:    next = EW_G;
            EW_G:    next = EW_Y;
            EW_Y:    next = NS_G;
            default: next = NS_G;
        endcase
        limit = (state == NS_G || state == EW_G) ? 16'(GREEN_CYCLES - 1)
                                                 : 16'(YELLOW_CYCLES - 1);
    end
    always_ff @(posedge clk) begin
        if (rst) begin
            state <= NS_G;
            timer <= '0;
        end else if (timer == limit) begin
            state <= next;
            timer <= '0;
        end else begin
            timer <= timer + 1'b1;
        end
    end
    always_comb begin
        ns = 3'b001;
        ew = 3'b001;
        case (state)
            NS_G:    ns = 3'b100;
            NS_Y:    ns = 3'b010;
            EW_G:    ew = 3'b100;
            EW_Y:    ew = 3'b010;
            default: ;
        endcase
    end
endmodule

// True dual-port synchronous RAM, single clock, read-first on both ports.
// If both ports write the same address in the same cycle, port B wins
// (behaviour is tool/vendor-dependent - avoid it in real designs).
module dual_port_ram #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 256
)(
    input  logic                     clk,
    input  logic                     we_a, we_b,
    input  logic [$clog2(DEPTH)-1:0] addr_a, addr_b,
    input  logic [WIDTH-1:0]         din_a, din_b,
    output logic [WIDTH-1:0]         dout_a, dout_b
);
    logic [WIDTH-1:0] mem [0:DEPTH-1];
    always_ff @(posedge clk) begin
        if (we_a) mem[addr_a] <= din_a;
        if (we_b) mem[addr_b] <= din_b;
        dout_a <= mem[addr_a];
        dout_b <= mem[addr_b];
    end
endmodule

// Register file with two asynchronous read ports and one synchronous write
// port. Register 0 is hard-wired to zero (RISC-V x0 convention).
// BYPASS = 1 forwards write data to a read port when reading the register
// being written in the same cycle (write-through); BYPASS = 0 returns old data.
module register_file #(
    parameter int WIDTH  = 32,
    parameter int REGS   = 32,
    parameter bit BYPASS = 1'b0
)(
    input  logic                     clk, we,
    input  logic [$clog2(REGS)-1:0]  waddr, raddr1, raddr2,
    input  logic [WIDTH-1:0]         wdata,
    output logic [WIDTH-1:0]         rdata1, rdata2
);
    logic [WIDTH-1:0] regs [0:REGS-1];
    always_ff @(posedge clk) begin
        if (we && waddr != '0) regs[waddr] <= wdata;
    end
    always_comb begin
        if (raddr1 == '0)                                    rdata1 = '0;
        else if (BYPASS && we && waddr == raddr1)            rdata1 = wdata;
        else                                                 rdata1 = regs[raddr1];
        if (raddr2 == '0)                                    rdata2 = '0;
        else if (BYPASS && we && waddr == raddr2)            rdata2 = wdata;
        else                                                 rdata2 = regs[raddr2];
    end
endmodule

// Asynchronous-read ROM. Contents come from a hex file (one word per line,
// $readmemh format) given by INIT_FILE; all-zero if INIT_FILE is empty.
module rom #(
    parameter int    WIDTH     = 8,
    parameter int    DEPTH     = 16,
    parameter string INIT_FILE = ""
)(
    input  logic [$clog2(DEPTH)-1:0] addr,
    output logic [WIDTH-1:0]         data
);
    logic [WIDTH-1:0] mem [0:DEPTH-1];
    initial begin
        for (int i = 0; i < DEPTH; i++) mem[i] = '0;
        if (INIT_FILE != "") $readmemh(INIT_FILE, mem);
    end
    assign data = mem[addr];
endmodule

// Single-port synchronous RAM, read-first: on a write cycle dout shows the
// OLD contents of the addressed word. DEPTH >= 2.
module single_port_ram #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 256
)(
    input  logic                     clk, we,
    input  logic [$clog2(DEPTH)-1:0] addr,
    input  logic [WIDTH-1:0]         din,
    output logic [WIDTH-1:0]         dout
);
    logic [WIDTH-1:0] mem [0:DEPTH-1];
    always_ff @(posedge clk) begin
        if (we) mem[addr] <= din;
        dout <= mem[addr];
    end
endmodule

// Asynchronous FIFO (Cummings-style, Gray-coded pointers)
// - DEPTH must be a power of 2
// - rdata is registered: valid the cycle AFTER r_en is accepted
// - wfull / rempty are registered and computed from the NEXT pointers (fixes flag lag)
module async_fifo #(
  parameter int WIDTH = 8,
  parameter int DEPTH = 16
)(
  // write domain
  input  logic             wclk, wrst,
  input  logic             w_en,
  input  logic [WIDTH-1:0] wdata,
  output logic             wfull,
  // read domain
  input  logic             rclk, rrst,
  input  logic             r_en,
  output logic [WIDTH-1:0] rdata,
  output logic             rempty
);
  localparam int AW = $clog2(DEPTH);
  logic [WIDTH-1:0] mem [0:DEPTH-1];
  logic [AW:0] wbin, wbin_next, wgray, wgray_next;
  logic [AW:0] rbin, rbin_next, rgray, rgray_next;
  logic [AW:0] rgray_wq1, rgray_wq2;   // read ptr synced into write domain
  logic [AW:0] wgray_rq1, wgray_rq2;   // write ptr synced into read domain
  wire winc = w_en && !wfull;
  wire rinc = r_en && !rempty;
  // ---------------- write domain ----------------
  assign wbin_next  = wbin + (AW+1)'(winc);
  assign wgray_next = (wbin_next >> 1) ^ wbin_next;
  wire wfull_val = (wgray_next == {~rgray_wq2[AW:AW-1], rgray_wq2[AW-2:0]});
  always_ff @(posedge wclk) begin
    if (winc) mem[wbin[AW-1:0]] <= wdata;
    if (wrst) begin
      wbin <= '0; wgray <= '0; wfull <= 1'b0;
    end else begin
      wbin <= wbin_next; wgray <= wgray_next; wfull <= wfull_val;
    end
  end
  // read ptr -> write domain (2-flop sync)
  always_ff @(posedge wclk)
    if (wrst) {rgray_wq2, rgray_wq1} <= '0;
    else      {rgray_wq2, rgray_wq1} <= {rgray_wq1, rgray};
  // ---------------- read domain ----------------
  assign rbin_next  = rbin + (AW+1)'(rinc);
  assign rgray_next = (rbin_next >> 1) ^ rbin_next;
  wire rempty_val = (rgray_next == wgray_rq2);
  always_ff @(posedge rclk) begin
    if (rrst) begin
      rbin <= '0; rgray <= '0; rempty <= 1'b1; rdata <= '0;
    end else begin
      if (rinc) rdata <= mem[rbin[AW-1:0]];
      rbin <= rbin_next; rgray <= rgray_next; rempty <= rempty_val;
    end
  end
  // write ptr -> read domain (2-flop sync)
  always_ff @(posedge rclk)
    if (rrst) {wgray_rq2, wgray_rq1} <= '0;
    else      {wgray_rq2, wgray_rq1} <= {wgray_rq1, wgray};
endmodule

// Synchronous FIFO, any DEPTH >= 2. dout is registered: valid the cycle
// AFTER rd_en is accepted. Writes when full and reads when empty are ignored.
// A simultaneous read+write while full performs the read only; while empty,
// the write only.
module sync_fifo #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16
)(
    input  logic             clk, rst,
    input  logic             wr_en, rd_en,
    input  logic [WIDTH-1:0] din,
    output logic [WIDTH-1:0] dout,
    output logic             full, empty
);
    localparam int AW = $clog2(DEPTH);
    initial if (DEPTH < 2) $error("sync_fifo: DEPTH must be >= 2");
    logic [WIDTH-1:0] mem [0:DEPTH-1];
    logic [AW:0]      count;
    logic [AW-1:0]    wp, rp;
    wire do_wr = wr_en && !full;
    wire do_rd = rd_en && !empty;
    assign full  = (count == (AW+1)'(DEPTH));
    assign empty = (count == '0);
    always_ff @(posedge clk) begin
        if (rst) begin
            wp    <= '0;
            rp    <= '0;
            count <= '0;
            dout  <= '0;
        end else begin
            if (do_wr) begin
                mem[wp] <= din;
                wp      <= (wp == AW'(DEPTH-1)) ? '0 : wp + 1'b1;
            end
            if (do_rd) begin
                dout <= mem[rp];
                rp   <= (rp == AW'(DEPTH-1)) ? '0 : rp + 1'b1;
            end
            case ({do_wr, do_rd})
                2'b10:   count <= count + 1'b1;
                2'b01:   count <= count - 1'b1;
                default: count <= count;
            endcase
        end
    end
endmodule

// UART receiver: 8N1, LSB first. CLK_PER_BIT = clk_freq / baud (>= 2).
// rx is synchronised internally. The start bit is re-checked at its middle
// (glitches are rejected) and every later bit is sampled at its centre.
// valid pulses for one cycle when data is ready; frame_err pulses with it
// if the stop bit was not high.
module uart_rx #(
    parameter int CLK_PER_BIT = 434
)(
    input  logic       clk, rst,
    input  logic       rx,
    output logic [7:0] data,
    output logic       valid,
    output logic       frame_err
);
    localparam int CW   = $clog2(CLK_PER_BIT);
    localparam int HALF = CLK_PER_BIT / 2;
    initial if (CLK_PER_BIT < 2) $error("uart_rx: CLK_PER_BIT must be >= 2");
    typedef enum logic [1:0] {IDLE, START, DATA, STOP} state_t;
    state_t state;
    logic [CW-1:0] count;
    logic [2:0]    bit_idx;
    logic [7:0]    shift;
    logic          rx_s1, rx_s2;
    always_ff @(posedge clk) begin
        if (rst) begin
            rx_s1 <= 1'b1;
            rx_s2 <= 1'b1;
        end else begin
            rx_s1 <= rx;
            rx_s2 <= rx_s1;
        end
    end
    always_ff @(posedge clk) begin
        valid     <= 1'b0;
        frame_err <= 1'b0;
        if (rst) begin
            state   <= IDLE;
            count   <= '0;
            bit_idx <= '0;
            shift   <= '0;
            data    <= '0;
        end else begin
            case (state)
                IDLE: begin
                    count <= '0;
                    if (!rx_s2) state <= START;           // falling edge seen
                end
                START: begin                              // wait to the middle of the start bit
                    if (count == CW'(HALF - 1)) begin
                        count <= '0;
                        if (!rx_s2) begin
                            bit_idx <= '0;
                            state   <= DATA;
                        end else
                            state <= IDLE;                // glitch, not a real start bit
                    end else
                        count <= count + 1'b1;
                end
                DATA: begin
                    if (count == CW'(CLK_PER_BIT - 1)) begin
                        count <= '0;
                        shift <= {rx_s2, shift[7:1]};     // LSB arrives first
                        if (bit_idx == 3'd7) state <= STOP;
                        else                 bit_idx <= bit_idx + 1'b1;
                    end else
                        count <= count + 1'b1;
                end
                STOP: begin
                    if (count == CW'(CLK_PER_BIT - 1)) begin
                        count     <= '0;
                        data      <= shift;
                        valid     <= 1'b1;
                        frame_err <= ~rx_s2;
                        state     <= IDLE;
                    end else
                        count <= count + 1'b1;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

// UART transmitter: 8N1, LSB first. CLK_PER_BIT = clk_freq / baud (>= 2).
// Pulse start for one cycle while busy = 0; data is latched on that cycle.
// busy stays high through the stop bit, so back-to-back frames are gapless.
module uart_tx #(
    parameter int CLK_PER_BIT = 434
)(
    input  logic       clk, rst,
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);
    localparam int CW = $clog2(CLK_PER_BIT);
    initial if (CLK_PER_BIT < 2) $error("uart_tx: CLK_PER_BIT must be >= 2");
    logic [CW-1:0] count;
    logic [3:0]    bit_idx;
    logic [9:0]    shreg;            // {stop, d7..d0, start}
    always_ff @(posedge clk) begin
        if (rst) begin
            tx      <= 1'b1;
            busy    <= 1'b0;
            count   <= '0;
            bit_idx <= '0;
            shreg   <= '0;
        end else if (start && !busy) begin
            shreg   <= {1'b1, data, 1'b0};
            busy    <= 1'b1;
            count   <= '0;
            bit_idx <= '0;
            tx      <= 1'b0;                          // start bit
        end else if (busy) begin
            if (count == CW'(CLK_PER_BIT - 1)) begin
                count   <= '0;
                bit_idx <= bit_idx + 1'b1;
                shreg   <= {1'b1, shreg[9:1]};
                tx      <= shreg[1];                  // next bit: d0..d7, then stop
                if (bit_idx == 4'd9) begin            // stop bit finished
                    busy <= 1'b0;
                    tx   <= 1'b1;
                end
            end else begin
                count <= count + 1'b1;
            end
        end
    end
endmodule

// Toggle-based req/ack handshake synchronizer for MULTI-BIT data across clock domains.
// Data is held stable in the source domain until the destination acknowledges,
// so only the 1-bit req/ack toggles cross the boundary (through 2-flop syncs).
// Pulse src_send only while src_busy is low; src_data is latched on that cycle.
module handshake_synchronizer #(
  parameter int WIDTH = 8
)(
  input  logic             src_clk, src_rst,
  input  logic             src_send,
  input  logic [WIDTH-1:0] src_data,
  output logic             src_busy,   // high from send until ack returns
  output logic             src_done,   // 1-cycle pulse when transfer completes
  input  logic             dst_clk, dst_rst,
  output logic [WIDTH-1:0] dst_data,
  output logic             dst_valid   // 1-cycle pulse, dst_data valid
);
  logic [WIDTH-1:0] data_hold;
  logic req_t, ack_t;
  logic rq1, rq2, rq2d;   // req_t synced to dst
  logic aq1, aq2, aq2d;   // ack_t synced to src
  assign src_busy = (req_t != aq2);
  // source domain
  always_ff @(posedge src_clk) begin
    if (src_rst) begin
      req_t <= 1'b0; data_hold <= '0;
      aq1 <= 1'b0; aq2 <= 1'b0; aq2d <= 1'b0; src_done <= 1'b0;
    end else begin
      if (src_send && !src_busy) begin
        data_hold <= src_data;
        req_t     <= ~req_t;
      end
      aq1 <= ack_t; aq2 <= aq1; aq2d <= aq2;
      src_done <= aq2 ^ aq2d;
    end
  end
  // destination domain
  always_ff @(posedge dst_clk) begin
    if (dst_rst) begin
      rq1 <= 1'b0; rq2 <= 1'b0; rq2d <= 1'b0;
      ack_t <= 1'b0; dst_data <= '0; dst_valid <= 1'b0;
    end else begin
      rq1 <= req_t; rq2 <= rq1; rq2d <= rq2;
      dst_valid <= 1'b0;
      if (rq2 ^ rq2d) begin
        dst_data  <= data_hold;   // stable: source is busy until ack
        dst_valid <= 1'b1;
        ack_t     <= rq2;
      end
    end
  end
endmodule

// Toggle-based pulse synchronizer: a 1-cycle pulse in src_clk becomes a
// 1-cycle pulse in dst_clk. Source pulses must be spaced by at least
// ~3 dst_clk cycles + 1 src_clk cycle or they can merge. Reset both domains together.
module pulse_synchronizer (
    input  logic src_clk, src_rst,
    input  logic src_pulse,
    input  logic dst_clk, dst_rst,
    output logic dst_pulse
);
    logic toggle;
    (* ASYNC_REG = "TRUE" *) logic q1, q2;
    logic q2d;
    always_ff @(posedge src_clk) begin
        if (src_rst)        toggle <= 1'b0;
        else if (src_pulse) toggle <= ~toggle;
    end
    always_ff @(posedge dst_clk) begin
        if (dst_rst) begin
            q1 <= 1'b0; q2 <= 1'b0; q2d <= 1'b0; dst_pulse <= 1'b0;
        end else begin
            q1 <= toggle; q2 <= q1; q2d <= q2;
            dst_pulse <= q2 ^ q2d;
        end
    end
endmodule

// Two-flop synchronizer for a SINGLE-BIT level signal entering clk's domain.
// Never use it on multi-bit buses (use handshake or async FIFO instead).
module two_flop_synchronizer #(
    parameter int STAGES = 2
)(
    input  logic clk, rst,
    input  logic async_in,
    output logic sync_out
);
    (* ASYNC_REG = "TRUE" *) logic [STAGES-1:0] sr;
    always_ff @(posedge clk) begin
        if (rst) sr <= '0;
        else     sr <= {sr[STAGES-2:0], async_in};
    end
    assign sync_out = sr[STAGES-1];
endmodule

// AXI4-Lite interface (all five channels) with master/slave modports.
// Valid/ready handshakes follow the AXI rules; drive everything from aclk.
interface axi_lite_if #(
    parameter int ADDR_WIDTH = 32,
    parameter int DATA_WIDTH = 32
)(
    input logic aclk,
    input logic aresetn
);
    // write address
    logic [ADDR_WIDTH-1:0]   awaddr;
    logic [2:0]              awprot;
    logic                    awvalid, awready;
    // write data
    logic [DATA_WIDTH-1:0]   wdata;
    logic [DATA_WIDTH/8-1:0] wstrb;
    logic                    wvalid, wready;
    // write response
    logic [1:0]              bresp;
    logic                    bvalid, bready;
    // read address
    logic [ADDR_WIDTH-1:0]   araddr;
    logic [2:0]              arprot;
    logic                    arvalid, arready;
    // read data
    logic [DATA_WIDTH-1:0]   rdata;
    logic [1:0]              rresp;
    logic                    rvalid, rready;
    modport master (
        input  aclk, aresetn,
        output awaddr, awprot, awvalid, wdata, wstrb, wvalid, bready,
               araddr, arprot, arvalid, rready,
        input  awready, wready, bresp, bvalid, arready, rdata, rresp, rvalid
    );
    modport slave (
        input  aclk, aresetn,
        input  awaddr, awprot, awvalid, wdata, wstrb, wvalid, bready,
               araddr, arprot, arvalid, rready,
        output awready, wready, bresp, bvalid, arready, rdata, rresp, rvalid
    );
endinterface

// Small ALU that uses an enum-typed opcode (a typed-enum example, not an FSM).
module enum_fsm_alu (
    input  logic [3:0] a, b,
    input  logic [1:0] op,
    output logic [3:0] y,
    output logic       zero
);
    typedef enum logic [1:0] {ADD, SUB, AND_OP, OR_OP} op_t;
    op_t operation;
    always_comb begin
        operation = op_t'(op);          // explicit cast: int -> enum
        case (operation)
            ADD:     y = a + b;
            SUB:     y = a - b;
            AND_OP:  y = a & b;
            OR_OP:   y = a | b;
            default: y = '0;
        endcase
    end
    assign zero = (y == '0);
endmodule

// Every req must be followed by ack within 1 to 3 clock cycles.
module sv_assertions_example (
    input logic clk, rst,
    input logic req, ack
);
    property p_req_gets_ack;
        @(posedge clk) disable iff (rst)
            req |-> ##[1:3] ack;
    endproperty
    a_req_gets_ack: assert property (p_req_gets_ack)
        else $error("ack did not follow req within 3 cycles");
    c_req_gets_ack: cover property (p_req_gets_ack);
endmodule

package sv_package_example;
    parameter int DATA_WIDTH = 32;
    typedef enum logic [1:0] {IDLE, BUSY, DONE, ERROR} status_t;
    // XOR-reduction parity: 1 when the number of set bits is odd
    function automatic logic parity(input logic [DATA_WIDTH-1:0] data);
        return ^data;
    endfunction
endpackage

`timescale 1ns/1ps
// Free-running clock. PERIOD is in ns (real, so odd/fractional periods are exact).
module clock_generator #(
    parameter real PERIOD = 10.0
)(
    output logic clk
);
    initial begin
        clk = 1'b0;
        forever #(PERIOD/2.0) clk = ~clk;
    end
endmodule

`timescale 1ns/1ps
// Active-high reset asserted from time 0 and held for CYCLES rising clock edges
// (the DUT samples rst = 1 on exactly CYCLES edges). Non-blocking updates avoid
// races with logic clocked by the same edge.
module reset_generator #(
    parameter int CYCLES = 2
)(
    input  logic clk,
    output logic rst
);
    int count;
    initial begin
        rst   = 1'b1;
        count = 0;
    end
    always @(posedge clk) begin
        if (count < CYCLES) count <= count + 1;
        if (count == CYCLES - 1) rst <= 1'b0;
    end
endmodule

`timescale 1ns/1ps
module tb_full_adder;
    logic a, b, cin;
    logic sum, cout;
    logic [1:0] expected;
    full_adder dut (.a(a), .b(b), .cin(cin), .sum(sum), .cout(cout));
    initial begin
        for (int i = 0; i < 8; i++) begin
            {a, b, cin} = 3'(i);
            #1;
            expected = 2'(a) + 2'(b) + 2'(cin);      // arithmetic reference
            if ({cout, sum} !== expected)
                $fatal(1, "full_adder FAIL: a=%b b=%b cin=%b -> cout=%b sum=%b",
                       a, b, cin, cout, sum);
        end
        $display("tb_full_adder PASS");
        $finish;
    end
endmodule

`timescale 1ns/1ps
// Self-checking sync FIFO testbench (scoreboard + flag checks).
// Run with different depths:  -Ptb_sync_fifo.DEPTH=4  /  =5 (non power of two)
module tb_sync_fifo;
    parameter int WIDTH = 8;
    parameter int DEPTH = 4;
    logic             clk = 0, rst = 1, wr_en = 0, rd_en = 0;
    logic [WIDTH-1:0] din = '0, dout;
    logic             full, empty;
    int               errors = 0;
    always #5 clk = ~clk;
    sync_fifo #(.WIDTH(WIDTH), .DEPTH(DEPTH)) dut (
        .clk(clk), .rst(rst), .wr_en(wr_en), .rd_en(rd_en),
        .din(din), .dout(dout), .full(full), .empty(empty));
    // scoreboard
    logic [WIDTH-1:0] q [$];
    logic [WIDTH-1:0] exp_d;
    logic             chk = 0;
    always @(posedge clk) begin
        if (chk && dout !== exp_d) begin
            $display("DATA MISMATCH t=%0t dout=%0h exp=%0h", $time, dout, exp_d);
            errors++;
        end
        chk = 0;
        if (rst) q.delete();
        else begin
            if (rd_en && q.size() > 0) begin exp_d = q.pop_front(); chk = 1; end
            // write uses pre-edge occupancy: a write on a full FIFO is dropped
            if (wr_en && (q.size() + (chk ? 1 : 0)) < DEPTH) q.push_back(din);
        end
    end
    // flag check, mid-cycle
    always @(negedge clk) if (!rst) begin
        if (full  !== (q.size() == DEPTH)) begin $display("FULL flag wrong t=%0t",  $time); errors++; end
        if (empty !== (q.size() == 0))     begin $display("EMPTY flag wrong t=%0t", $time); errors++; end
    end
    initial begin
        repeat (3) @(posedge clk);
        #1 rst = 0;
        // fill beyond capacity
        repeat (DEPTH + 3) begin @(posedge clk); #1 wr_en = 1; din = $urandom; end
        @(posedge clk); #1 wr_en = 0;
        // drain beyond empty
        repeat (DEPTH + 3) begin @(posedge clk); #1 rd_en = 1; end
        @(posedge clk); #1 rd_en = 0;
        // random mixed traffic
        repeat (2000) begin
            @(posedge clk); #1;
            wr_en = ($urandom_range(0, 99) < 55);
            rd_en = ($urandom_range(0, 99) < 45);
            din   = $urandom;
        end
        @(posedge clk); #1 wr_en = 0; rd_en = 0;
        repeat (3) @(posedge clk);
        if (errors == 0) $display("tb_sync_fifo PASS (DEPTH=%0d)", DEPTH);
        else             $fatal(1, "tb_sync_fifo FAIL (%0d errors)", errors);
        $finish;
    end
endmodule

`timescale 1ns/1ps
module tb_up_down_counter;
    localparam int WIDTH = 4;
    logic             clk = 0, rst = 1, en = 0, up = 1;
    logic [WIDTH-1:0] q;
    logic [WIDTH-1:0] model;
    int               errors = 0;
    always #5 clk = ~clk;
    up_down_counter #(.WIDTH(WIDTH)) dut (.clk(clk), .rst(rst), .en(en), .up(up), .q(q));
    // reference model, updated on the same edge using pre-edge inputs
    always @(posedge clk) begin
        if (rst)     model <= '0;
        else if (en) model <= up ? model + 1'b1 : model - 1'b1;
    end
    // compare every cycle just before the next edge
    always @(negedge clk) begin
        if (q !== model) begin
            $display("MISMATCH t=%0t q=%0d model=%0d", $time, q, model);
            errors++;
        end
    end
    initial begin
        repeat (2) @(posedge clk);
        #1 rst = 0; en = 1; up = 1;
        repeat (20) @(posedge clk);          // counts up and wraps 15 -> 0
        #1 up = 0;
        repeat (20) @(posedge clk);          // counts down and wraps 0 -> 15
        #1 en = 0;
        repeat (4) @(posedge clk);           // holds
        #1 rst = 1;
        repeat (2) @(posedge clk);
        #1;
        if (q !== '0) errors++;
        if (errors == 0) $display("tb_up_down_counter PASS");
        else             $fatal(1, "tb_up_down_counter FAIL (%0d errors)", errors);
        $finish;
    end
endmodule
